import React from "react";

const Products = () => {
    return(
        <div>
            <h1 style={{fontSize:"large", textAlign:"center"}}>PRODUCTS</h1>
            <div>
                <table style={{width:"70%", borderCollapse:"collapse", marginTop:"100px",marginLeft:"20%"}}>
                    <th>IMAGE</th>
                    <th>NAME</th>
                    <th>CATEGORY</th>
                    <th>PRICE</th>
                    <th>BRAND</th>
                    <th>ACTIONS</th>
                </table>
            </div>
            <div><box> hef</box></div>
        </div>
    )
};
export default Products;
